/// <reference types="node" />
// Periodic table data (docs/packs.md "Other bundled data"): `node tools/elements/build.ts`.
// Runs on the developer's computer, never in the app; the app reads the generated file offline.
import { writeFileSync } from 'node:fs';

const SOURCE = 'https://pubchem.ncbi.nlm.nih.gov/rest/pug/periodictable/JSON';
const OUT = 'src/features/tools/elements-data.ts';

type Table = { Table: { Columns: { Column: string[] }; Row: { Cell: string[] }[] } };

const { Table } = (await (await fetch(SOURCE)).json()) as Table;
const col = (name: string) => {
  const i = Table.Columns.Column.indexOf(name);
  if (i < 0) throw new Error(`PubChem table has no ${name} column`);
  return i;
};
const [num, sym, name, mass, config, block] = ['AtomicNumber', 'Symbol', 'Name', 'AtomicMass', 'ElectronConfiguration', 'GroupBlock'].map(col);
const rows = Table.Row.map(({ Cell: c }) => [Number(c[num]), c[sym], c[name], c[mass], c[config], c[block]]);
if (rows.length !== 118 || rows.some((r, i) => r[0] !== i + 1)) throw new Error('Expected elements 1–118 in order');

writeFileSync(
  OUT,
  `// Generated by tools/elements/build.ts — don't edit by hand.
// Source: PubChem Periodic Table (${SOURCE}), National Library of Medicine.
// License: public domain (US Government work); retrieved ${new Date().toISOString().slice(0, 10)}.
// [atomic number, symbol, name, atomic mass, electron configuration, group block]
export const ELEMENT_ROWS: [number, string, string, string, string, string][] = [
${rows.map((r) => `  ${JSON.stringify(r).replace(/"/g, "'")},`).join('\n')}
];
`,
);
console.log(`Wrote ${rows.length} elements to ${OUT}`);
